804:     descriptors: readonly DeepReadonly<IdentityVersionDescriptor>[];
805:     assessments: readonly ContinuityAssessment[];
806:   },
807:   binding: ConditionalVersionBinding,
808:   candidateID: IdentityVersionID,
809:   policy: Policy,
810:   ctx: TemporalContext,
811: ): BindingResult {
812:   const candidate = state.descriptors.find((descriptor) => descriptor.id === candidateID);
813:   if (candidate === undefined) {
814:     return mechanismResult(
815:       mechanismFailure('E_UNKNOWN_BOUNDARY_REJECTED', `Candidate descriptor ${candidateID} is not supplied`),
